<div class="page-heading"><div><div class="eyebrow">Akun pelaku usaha eksternal</div><h1>Profil dan verifikasi pelaku usaha</h1><p>Pelaku usaha dapat mewakili perusahaan setelah nomor telepon, rekomendasi dinas, dan hubungan dengan perusahaan disetujui.</p></div><?php if ($this->metro->can($current_user->id,'self.delegation.view')): ?><a class="button outline" href="<?= site_url('pelimpahan') ?>">Pelimpahan perusahaan</a><?php endif; ?></div>
<section class="card form-card"><div class="section-heading compact"><div><h2>Status verifikasi dinas</h2><p><?= e($profile->review_note ?: 'Petugas akan memeriksa nomor rekomendasi.') ?></p><?php if ($profile->recommendation_head): ?><small>Rekomendasi kepala dinas: <?= e($profile->recommendation_head) ?></small><?php endif; ?></div><span class="badge <?= $profile->verification_status==='approved'?'success':($profile->verification_status==='pending'?'info':'danger') ?>"><?= e($profile->verification_status==='approved'?'Disetujui':($profile->verification_status==='pending'?'Menunggu':'Ditolak')) ?></span></div><?php if ($this->metro->can($current_user->id,'self.technician_profile.update')): ?><form method="post" action="<?= site_url('profil-teknisi') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="form-grid"><label>Nama pelaku usaha<input value="<?= e($current_user->full_name) ?>" disabled></label><label>Nomor telepon<input value="<?= e($current_user->phone) ?>" disabled></label><label class="span-2">Nomor rekomendasi dinas<input name="recommendation_number" maxlength="120" value="<?= e($profile->recommendation_number) ?>" placeholder="Nomor surat / rekomendasi yang dapat diperiksa dinas"></label><label>Nomor TDUR<input name="tdur_number" maxlength="120" value="<?= e($profile->tdur_number) ?>"></label><input type="hidden" name="scope_present" value="1"><div class="span-2"><strong>Jenis UTTP sesuai kewenangan TDUR</strong><div class="tdur-scope-grid"><?php $selected_scope=(array)json_decode((string)$profile->tdur_scope,TRUE);foreach ($scope_types as $type): ?><label><input type="checkbox" name="tdur_scope[]" value="<?= (int)$type->id ?>"<?= in_array((int)$type->id,array_map('intval',$selected_scope),TRUE)?' checked':'' ?>> <?= e($type->type_name) ?></label><?php endforeach; ?></div></div><label class="span-2">Catatan rekomendasi <small>opsional</small><textarea name="recommendation_note" rows="3" maxlength="2000"><?= e($profile->recommendation_note) ?></textarea></label></div><p class="muted small">Perubahan data rekomendasi setelah persetujuan akan meminta penilaian ulang dinas.</p><button class="button primary" type="submit">Simpan profil pelaku usaha</button></form><?php endif; ?></section>
<?php if ($current_user->phone_verification_required): ?><section class="card form-card phone-verification"><div class="section-heading compact"><div><h2>Verifikasi nomor WhatsApp</h2><p><?= $current_user->phone_verified_at?'Nomor sudah terverifikasi.':'Masukkan kode WhatsApp. Bila bot tidak tersedia, minta kode manual kepada petugas.' ?></p></div><span class="badge <?= $current_user->phone_verified_at?'success':'danger' ?>"><?= $current_user->phone_verified_at?'Terverifikasi':'Belum diverifikasi' ?></span></div><?php if (!$current_user->phone_verified_at): ?><form method="post" action="<?= site_url('verifikasi-telepon') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><label>Kode 6 digit<input name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="one-time-code"></label><button class="button primary" type="submit">Verifikasi nomor</button></form><form method="post" action="<?= site_url('verifikasi-telepon/kirim-ulang') ?>" class="phone-resend-form"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="button outline small-button" type="submit">Kirim ulang via WhatsApp</button></form><?php endif; ?></section><?php endif; ?>

