<section class="card form-card"><h2>Dokumen pendukung</h2><p class="muted">Unggah TDUR, surat rekomendasi, atau dokumen lain dalam format PDF. Beberapa berkas dapat dipilih sekaligus.</p><form method="post" enctype="multipart/form-data" action="<?= site_url('pelaku-usaha/'.$current_user->id.'/dokumen') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="form-grid"><label>Jenis dokumen<select name="document_type"><option value="tdur">TDUR</option><option value="recommendation">Rekomendasi dinas</option><option value="other">Lainnya</option></select></label><label>Berkas PDF<input type="file" name="documents[]" accept="application/pdf,.pdf" multiple required></label></div><button class="button primary" type="submit">Unggah dokumen</button></form><div class="document-list"><?php foreach ($support_documents as $document): ?><div class="document-row"><a href="<?= site_url('pelaku-usaha/dokumen/'.$document->id) ?>" target="_blank" rel="noopener"><?= e($document->original_name) ?></a><small><?= e(strtoupper($document->document_type)) ?> · <?= e(tanggal_id($document->created_at,TRUE)) ?></small><form method="post" action="<?= site_url('pelaku-usaha/dokumen/'.$document->id.'/hapus') ?>" onsubmit="return confirm('Hapus dokumen ini?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link danger" type="submit">Hapus</button></form></div><?php endforeach; ?></div></section>
